        return x / (1 + k*np.abs(x))

    def second(x, k):
        return np.column_stack((np.tanh(k*x), x*np.roll(x, -1, axis=1)))

    p = _operator(u, panel['v1'], first, (0.03, 5.0))(q)
    r = _operator(u, panel['v2'], second, (0.15, 3.0))(q)
    return p, r


