    p, r = _operators(study['panel_c'], _coordinates(study['panel_a'], x))
    common = np.column_stack((p, r, np.einsum('ij,ij->i', p, r)))
    offdiag = np.column_stack([p[:, i]*r[:, j] for i in range(p.shape[1])
